import{_ as r,l as n,o as e,c as s,v as t,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"投影法","description":"","frontmatter":{"title":"投影法","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/projection-methods.md","filePath":"econ/projection-methods.md","lastUpdated":1789023840000}'),h={name:"econ/projection-methods.md"};function _(m,a,E,u,B,A){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="投影法" tabindex="-1">投影法 <a class="header-anchor" href="#投影法" aria-label="Permalink to &quot;投影法&quot;">​</a></h1><div class="epigraph"><p>把未知政策写成基函数的线性组合，让欧拉残差在加权意义上为零——配点或伽辽金，而不是只在一点泰勒。</p><footer>—— Judd, Projection Methods for Solving Nonlinear Dynamic Economic Models, 1992；Miranda and Fackler, Applied Computational Economics</footer></div><p><a href="/econ/perturbation-methods">上一课</a>的局部展开在不可微与大偏离处停下。本课缺口是<strong>全局逼近</strong>：残差投影到有限基上。不重写二阶张量，不把神经网络当新均衡概念。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧拉或贝尔曼残差 \\(R(s;g)\\) 应在状态空间上接近零。取基 \\(\\{\\psi_i\\}\\)，令 \\(g_N(s)=\\sum_{i=1}^N\\theta_i\\psi_i(s)\\)，选 \\(\\theta\\) 使 \\(\\langle R(\\cdot;g_N),\\phi_j\\rangle=0\\)。配点：\\(\\phi_j\\) 是点质量；伽辽金：\\(\\phi_j=\\psi_j\\)。Chebyshev 多项式在光滑问题上指数收敛；有 kinks 时分段或样条更合适。缺口是给 VFI 的插值网格一条「加权残差」的姐妹，而不是再讲压缩。</p><p><span class="marginnote">Time iteration 在欧拉上对政策迭代，常与配点结合。Collard 与 Juillard、Christiano–Fisher 的参数化期望，是同一族。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选域（资本、冲击的有界集）、基、积分节点（Gauss–Hermite 对正态冲击）。非线性求解 \\(\\theta\\)。维数灾难：状态超过三四维，张量积网格爆炸，改用稀疏网格、 Smolyak、或可分结构。异质主体：个人政策用投影，分布用直方图或模拟——后课 Aiyagari / KS。精度用 Euler 方程误差的判断标准（Judd）。</p>',8)),(e(),l(c,null,{default:o(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E5%87%BD%E6%95%B0%20g_N%22%5D%20--%3E%20RES%5B%22%E6%AC%A7%E6%8B%89%E6%AE%8B%E5%B7%AE%20R%22%5D%0A%20%20RES%20--%3E%20PROJ%5B%22%E9%85%8D%E7%82%B9%20%2F%20%E4%BC%BD%E8%BE%BD%E9%87%91%22%5D%0A%20%20PROJ%20--%3E%20TH%5B%22%E7%B3%BB%E6%95%B0%20%CE%B8%22%5D%0A%20%20TH%20--%3E%20ERR%5B%22%E6%AE%8B%E5%B7%AE%E8%AF%8A%E6%96%AD%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与扰动：同一模型可两套解交叉检验。平滑 NK 用扰动更快；偶尔绑定、非凸投资、离散劳动用投影或混合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是函数逼近加均衡残差正交。经济没有变：仍是欧拉加市场出清。变的是 \\(g\\) 的表示。基选错（全局多项式跨 kink）会造成振荡，看起来像多重均衡或古怪 IRF，其实是数值伪迹。诊断残差、加倍节点、对照 VFI，是同一课的纪律。</p><p>理性预期在投影里体现为：积分用模型自己的转移，不是用数据回归。适应性学习后课才把预期算子换成估计出来的信念。</p><p><span class="marginnote">Judd, <em>JEDC</em> 1992。McGrattan 对投影在宏观的早期应用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计参数（下一课校准）。高维 HANK 的序列空间方法（Boppart–Krusell–Mitman、Auclert 等）是另一条「沿时间路径线性化」的路，不在本课展开，但精神同为残差为零。不要把投影写成只有异质模型才需要：代表性非凸问题同样需要。</p><p>后课默认：全局解 = 投影 / VFI / 配点；局部解 = 扰动。下一课：有了能算的解，参数从哪里来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>投影用有限基配平欧拉残差，覆盖局部扰动够不到的域。</li><li>kinks 要用对的基；残差诊断防伪迹。</li><li>与 VFI 是姐妹，不是替代均衡定义。</li><li>出处：Judd, <em>JEDC</em> 1992；Miranda and Fackler。</li></ul>',10))])}const T=r(h,[["render",_]]);export{k as __pageData,T as default};
